def backfill_event_slugs(apps, schema_editor):
    """Give every existing event a slug that is unique inside its organization.

    Oldest first, so the event that has been sharing a name-derived link the
    longest keeps the unsuffixed slug.
    """
    from django.utils.text import slugify

    Event = apps.get_model('guests', 'Event')
    for event in Event.objects.filter(slug='').order_by('created_at', 'id'):
        taken = Event.objects.filter(organization_id=event.organization_id).exclude(pk=event.pk)
        base = slugify(event.name)[:72].strip('-') or 'event'
        candidate = base
        suffix = 2
        while taken.filter(slug=candidate).exists():
            candidate = f'{base}-{suffix}'
            suffix += 1
        event.slug = candidate
        event.save(update_fields=['slug'])


